diff --git a/torch/csrc/utils/python_numbers.h b/torch/csrc/utils/python_numbers.h
index 0d3fa2f5c..d147d4bf7 100644
--- a/torch/csrc/utils/python_numbers.h
+++ b/torch/csrc/utils/python_numbers.h
@@ -77,12 +77,16 @@ inline bool THPUtils_checkIndex(PyObject *obj) {

 inline int64_t THPUtils_unpackIndex(PyObject* obj) {
   if (!THPUtils_checkLong(obj)) {
-    auto index = THPObjectPtr(PyNumber_Index(obj));
+    auto num = PyNumber_Index(obj);
+    auto index = THPObjectPtr(num);
     if (index == nullptr) {
       throw python_error();
     }
     obj = index.get();
+    std::cout << "long value refcount " << obj->ob_refcnt << std::endl;
   }
+  // :(
+  std::cout << "long value refcount after THPObjectPtr goes out of scope " << obj->ob_refcnt << std::endl;
   return THPUtils_unpackLong(obj);
 }

And run this example program:
import torch
import torch.onnx.operators

x = torch.rand(345321)
print('***call view')
x.view(torch.tensor(345321))

Gives the following output
long value refcount after THPObjectPtr goes out of scope 4
***call view
long value refcount 1
long value refcount after THPObjectPtr goes out of scope 4556590640

Which looks awfully suspicious. Note I used a super rare integer value to avoid getting a pooled instance. I think it might be the case that we need to call THPUtils_unpackLong before the THPObjectPtr goes out of scope

🐛 Bug
Given the following code, the two sparse tensors constructed here appear identical, but produce two different results when added to a 0 tensor of the same shape.
#include <torch/torch.h>
#include <ATen/SparseTensorImpl.h>
#include <iostream>
#include <vector>

using at::Tensor;
using at::SparseTensorImpl;

Tensor make_sparse_from_indices(Tensor& indices, at::TensorOptions opts){
  at::Tensor vals = at::tensor({3, 0, 0, 9, 0, 0}, opts).view({2, 3});
  at::Tensor sparse = at::sparse_coo_tensor(indices, vals, {3, 3, 3}, opts);
  _get_sparse_impl(sparse)->set_coalesced(true);

  return sparse;
}

int main() {
  at::TensorOptions opts = at::device(at::kCUDA).dtype(at::kLong);

  Tensor inds1 = at::tensor({0, 1, 0, 0}, opts).view({2, 2});
  Tensor inds2 = inds1.transpose(0,1).clone().transpose(0,1);//.clone();

  Tensor sparse1 = make_sparse_from_indices(inds1, opts);
  Tensor sparse2 = make_sparse_from_indices(inds2, opts);

  Tensor z1 = at::zeros({3, 3, 3}, opts);
  std::cout << z1.add(sparse1) << std::endl;
  printf("\n===\n");
  std::cout << z1.add(sparse2) << std::endl;

  /* line 28 and line 29 do not produce the same result */
}
Un-commenting the call to clone() fixes the issue.  The answer might be  "Just use coalesce() instead of manually setting the flag", but the only reason this works is because coalesce() appears to always make a clone of indices*.  That strikes me as just another way of accomplishing the same thing & not fully answering why an extra call to clone() is needed.
This is a simplified reproduction of an issue that came up when trying to implement dense.to_sparse() (#12171).  When converting a dense tensor to sparse, we know there won't be any dupe indices, so I'm trying to determine whether I really need to call the entire coalesce() routine or not.
*unless is_coalesced is already true.
To Reproduce
See code snippet above.  Issue only appears on CUDA.
Expected behavior
both calls to add should return the same result
